function exportSaves(){
 try {
  const json=encodeBackup(manager);
  const file=new Blob([json],{type:'application/json;charset=utf-8'});
  const url=URL.createObjectURL(file);
  const link=document.createElement('a');link.href=url;link.download='ashen-pilgrimage-guardados.json';
  document.body.appendChild(link);link.click();link.remove();
  // La descarga no implica que el navegador haya guardado el fichero: el usuario debe comprobarlo.
  setTimeout(()=>URL.revokeObjectURL(url),1000);
  showMenu('backup','Descarga solicitada. Comprueba que el archivo JSON se haya guardado.');
 }catch(error){showMenu('backup',error.message||'No se pudo exportar el archivo.');}
}
function chooseBackupFile(){
 const picker=document.createElement('input');picker.type='file';picker.accept='.json,application/json';
 picker.addEventListener('change',async()=>{
  const file=picker.files?.[0];if(!file)return;
  if(file.size>BACKUP_MAX_BYTES)return showMenu('backup','El archivo supera el límite de 2 MB.');
  try {pendingImport=decodeBackup(await file.text());showMenu('confirm-import');}
  catch(error){pendingImport=null;showMenu('backup',error.message||'No se pudo leer la copia.');}
 });
 picker.click();
}
function hasPlayableSession(){return phase==='playing'||phase==='won'}
